using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
public void Execute(ExecutionResult result){var lines=new List<string>();foreach(string path in new[]{"Assets/Scenes/MireOfTheDamned_SourceGrid.unity","Assets/Scenes/SweetWater_SourceGrid.unity"}){var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var terrain=ts.Select(t=>t.GetComponent<Terrain>()).First(t=>t);var candidates=new List<System.Tuple<Transform,float>>();foreach(var t in ts.Where(t=>t.name.StartsWith("ApprovedReplacement_")&&t.gameObject.activeInHierarchy)){var rs=t.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();if(rs.Length==0)continue;float gap=rs.Min(r=>r.bounds.min.y)-terrain.SampleHeight(t.position)-terrain.transform.position.y;if(gap>.15f)candidates.Add(System.Tuple.Create(t,gap));}foreach(var q in candidates.OrderByDescending(q=>q.Item2).Take(3)){var t=q.Item1;lines.Add(s.name+"|"+t.parent.name+"|gap="+q.Item2+"|anchor="+t.parent.position.ToString("R")+"|visual="+t.position.ToString("R"));var go=new GameObject("QA Camera");var c=go.AddComponent<Camera>();c.farClipPlane=2000;c.fieldOfView=50;var target=t.position;target.y=terrain.SampleHeight(target)+terrain.transform.position.y+2;c.transform.position=target+new Vector3(12,5,-12);c.transform.LookAt(target);MMSequentialEvidence.Render(c,"Validation/StructuralQA/float_"+s.name+"_"+t.parent.name+".png",1000,800);UnityEngine.Object.DestroyImmediate(go);}}File.WriteAllLines("Validation/StructuralQA/float_probe.txt",lines);EditorSceneManager.OpenScene("Assets/Scenes/Enroth_Linked_OpenWorld.unity",OpenSceneMode.Single);result.Log(string.Join("\n",lines));}}

